def all_pairs() -> list[tuple[str, str, str]]:
    rows = [(left, right, "SAME_THREAD") for left, right in SAME_THREAD]
    rows.extend((left, right, "DIFFERENT_THREAD") for left, right in DIFFERENT_THREAD)
    return rows
